@test("the example")
def _():
    check_eq(build_url("https://api.example.com/v1/", ["users", "a/b", "books"], {"q": "café", "limit": None, "tags": ["x", "y"]}),
             "https://api.example.com/v1/users/a%2Fb/books?q=caf%C3%A9&tags=x&tags=y")

@test("bases and segments")
def _():
    check_eq(build_url("https://h.example", ["a", 5]), "https://h.example/a/5")
    check_eq(build_url("https://h.example/", []), "https://h.example")
    check_eq(build_url("https://h.example", ["sp ace", "q?x", "h#1", "100%"]), "https://h.example/sp%20ace/q%3Fx/h%231/100%25")

@test("query values")
def _():
    check_eq(build_url("https://h", ["s"], {"flag": True, "off": False}), "https://h/s?flag=true&off=false")
    check_eq(build_url("https://h", ["s"], {"a": "x&admin=1"}), "https://h/s?a=x%26admin%3D1")
    check_eq(build_url("https://h", ["s"], {"n": 0, "e": ""}), "https://h/s?n=0&e=")
    check_eq(build_url("https://h", ["s"], {"gone": None}), "https://h/s")
    check_eq(build_url("https://h", ["s"], {}), "https://h/s")
    check_eq(build_url("https://h", ["s"], {"t": ()}), "https://h/s")

